package com.bananalab.lite;
import android.content.*;
import org.json.*;import java.util.*;
/** The user's own questions with the sentence that was shown and, when given, the user's verdict. They are the only
 *  measure made with real questions: «bien» answers must stay; «mal» answers should change. */
final class RealExam{
 static final int MAX=200;
 interface Reader{String sentence(String question)throws Exception;}
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-real-questions",0);}
 static JSONArray rows(Context c)throws Exception{return new JSONArray(prefs(c).getString("rows","[]"));}
 static void save(Context c,JSONArray rows)throws Exception{prefs(c).edit().putString("rows",rows.toString()).apply();}
 static void record(Context c,String question,String sentence,String source){try{if(question==null||sentence==null||sentence.length()>700)return;JSONArray old=rows(c),next=new JSONArray();String key=ChatLanguage.normalize(question);for(int i=Math.max(0,old.length()-MAX+1);i<old.length();i++)if(!ChatLanguage.normalize(old.getJSONObject(i).getString("question")).equals(key))next.put(old.getJSONObject(i));next.put(new JSONObject().put("question",question).put("sentence",sentence).put("source",source).put("verdict","").put("time",System.currentTimeMillis()));save(c,next);}catch(Throwable ignored){}}
 /** Marks the most recent recorded answer. */
 static String mark(Context c,boolean good)throws Exception{JSONArray rows=rows(c);if(rows.length()==0)return "Todavía no tengo una respuesta mía sobre tus lecturas para anotar. Preguntame algo de lo que leí y después decime si estuvo bien o mal.";JSONObject last=rows.getJSONObject(rows.length()-1);last.put("verdict",good?"bien":"mal");save(c,rows);return good?"Anotado: esa respuesta estuvo bien. La uso como pregunta fija de mi examen con tus preguntas, para no perderla.\nPregunta: "+last.getString("question"):"Anotado: esa respuesta estuvo mal. Si sabés el dato correcto, decime «Te corrijo: …». En el examen con tus preguntas reviso si dejo de dar esa oración.\nPregunta: "+last.getString("question");}
 static String same(String a,String b){return a==null||b==null?"":new Lector.Flat(a,true).text.toString().equals(new Lector.Flat(b,true).text.toString())?"same":"other";}
 /** Asks every judged question again and compares with what was shown then. */
 static String run(Context c,Reader reader)throws Exception{JSONArray rows=rows(c);int good=0,kept=0,bad=0,changed=0,silent=0,pending=0;StringBuilder lost=new StringBuilder();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String verdict=r.getString("verdict");if(verdict.isEmpty()){pending++;continue;}String now=reader.sentence(r.getString("question"));if(verdict.equals("bien")){good++;if(same(now,r.getString("sentence")).equals("same"))kept++;else if(lost.length()<600)lost.append("\n· ").append(r.getString("question")).append(now==null?" → ahora no respondo":" → ahora elijo otra oración");}else{bad++;if(now==null)silent++;else if(same(now,r.getString("sentence")).equals("other"))changed++;}}
  if(good+bad==0)return "Todavía no calificaste ninguna respuesta. Después de una respuesta sobre tus lecturas decime «esa respuesta estuvo bien» o «esa respuesta estuvo mal»; con eso armo un examen con tus propias preguntas."+(pending>0?"\nTengo "+pending+" preguntas tuyas guardadas sin calificar.":"");
  JSONObject result=new JSONObject().put("time",System.currentTimeMillis()).put("good",good).put("kept",kept).put("bad",bad).put("changed",changed).put("silent",silent);prefs(c).edit().putString("last",result.toString()).apply();
  return "Examen con tus preguntas:\n· Respuestas que marcaste bien: conservo "+kept+" de "+good+"."+lost+"\n· Respuestas que marcaste mal: "+changed+" ahora dan otra oración, "+silent+" quedaron sin respuesta y "+(bad-changed-silent)+" siguen igual, de "+bad+".\nSin calificar: "+pending+".\nEs la única medida hecha con preguntas tuyas; son pocas, así que cada una pesa mucho.";}
 static String summary(Context c){try{JSONArray rows=rows(c);int good=0,bad=0;for(int i=0;i<rows.length();i++){String v=rows.getJSONObject(i).getString("verdict");if(v.equals("bien"))good++;else if(v.equals("mal"))bad++;}String last=prefs(c).getString("last","");String tail="";if(!last.isEmpty()){JSONObject r=new JSONObject(last);tail=" Último examen: conservé "+r.getInt("kept")+" de "+r.getInt("good")+" buenas.";}return "Tus preguntas reales: "+rows.length()+" guardadas · "+good+" marcadas bien · "+bad+" mal."+tail+(good+bad==0?" Decí «esa respuesta estuvo bien» o «…mal» después de una respuesta.":" Decí «examen con mis preguntas».");}catch(Throwable e){return "";}}
}
